3	// First-party event stream. Every product analytic — the activation funnel,
4	// retention cohorts, per-user journeys, attribution, the admin overview — is a
5	// query over this one table rather than its own bespoke tracking.
6	//
7	// Two rules keep it useful:
8	//
9	// 1. NAMES ARE A CLOSED SET. Free-text event names rot within weeks: three
10	//    spellings of the same thing, and every funnel query silently undercounts.
11	//    EVENTS below is the whole vocabulary; adding one is a deliberate edit.
12	// 2. PROPS ARE SMALL AND NON-PII. Ids, counts, short enum-ish strings. Never
13	//    prompt bodies, never generated content, never anything that would make
14	//    this table a second copy of user data with different retention rules.
15	
16	// NOTE: every name here must actually be emitted somewhere. Two acquisition
17	// names (landing.viewed, landing.prompt_submitted) were removed on 2026-08-22
18	// because nothing fired them — they needed a client-side beacon endpoint that
19	// was never built. Aspirational names are not free: the privacy policy is
20	// written from this list, so a name that never fires makes the policy describe
21	// collection that doesn't happen. Add them back together with the beacon, and
22	// update app/legal/privacy in the same change.
23	export const EVENTS = {
24	  // Activation — the path the North Star measures.
25	  signedUp: "user.signed_up",
26	  projectCreated: "project.created",
27	  // Churn signal, and the counterweight to projectCreated: a funnel that only
28	  // counts creations reads as growth while people are deleting everything.
29	  projectDeleted: "project.deleted",
30	  buildStarted: "build.started",
31	  buildSucceeded: "build.succeeded",
32	  buildFailed: "build.failed",
33	  // Explicit thumbs up/down on a finished build — the only signal here that is
34	  // a direct statement of satisfaction rather than an inference from behaviour.
35	  buildRated: "build.rated",
36	  sitePublished: "project.published",
37	
38	  // Monetization.
39	  creditsExhausted: "credits.exhausted",
40	  spendCapReached: "credits.cap_reached",
41	  checkoutStarted: "billing.checkout_started",
42	  creditsPurchased: "billing.credits_purchased",
43	} as const;
44	
45	export type EventName = (typeof EVENTS)[keyof typeof EVENTS];
46	
47	/**
48	 * The North Star: a user reaching their first PUBLISHED build. Not first
49	 * signup, not first generation — the moment the product delivered the thing
50	 * it promises, a real site at a real URL.
51	 */
52	export const NORTH_STAR: EventName = EVENTS.sitePublished;
53	
54	type Props = Record<string, string | number | boolean | null | undefined>;
55	
56	/**
57	 * Record an event. Deliberately fire-and-forget: analytics must never fail a
58	 * user's request or add latency to a build. A dropped event is a small gap in
59	 * a dashboard; a thrown one would be a failed generation.
60	 */
61	export function track(name: EventName, opts: { userId?: string | null; props?: Props } = {}): void {
62	  void db.event
63	    .create({
64	      data: {
65	        name,
66	        userId: opts.userId ?? null,
67	        props: opts.props ? (JSON.parse(JSON.stringify(opts.props)) as object) : undefined,
68	      },
69	    })
70	    .catch((err) => {
71	      // Log and move on — see above.
72	      console.error(`[events] failed to record ${name}:`, err);
73	    });
74	}
75	
76	export type FunnelStep = { step: string; event: EventName; users: number; pctOfPrevious: number | null };
77	
78	/**
79	 * Activation funnel: signup → first project → first successful build → first
80	 * publish, counted in DISTINCT USERS rather than events. Counting events would
81	 * let one enthusiastic user look like retention.
82	 */
83	export async function activationFunnel(sinceDays = 30): Promise<FunnelStep[]> {
84	  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60 * 1000);
85	
86	  const steps: { step: string; event: EventName }[] = [
87	    { step: "Signed up", event: EVENTS.signedUp },
88	    { step: "Created a project", event: EVENTS.projectCreated },
89	    { step: "Built successfully", event: EVENTS.buildSucceeded },
90	    { step: "Published a site", event: EVENTS.sitePublished },
91	  ];
92	
93	  const out: FunnelStep[] = [];
94	  let previous: number | null = null;
95	
96	  for (const s of steps) {
97	    const rows = await db.event.findMany({
98	      where: { name: s.event, createdAt: { gte: since }, userId: { not: null } },
99	      distinct: ["userId"],
100	      select: { userId: true },
101	    });
102	    const users = rows.length;
103	    out.push({
104	      ...s,
105	      users,
106	      pctOfPrevious: previous === null || previous === 0 ? null : Math.round((users / previous) * 1000) / 10,
107	    });
108	    previous = users;
109	  }
110	
111	  return out;
112	}
113	
114	/**
115	 * Green-build-first-try: the share of successful builds that compiled with no
116	 * repair attempt. A roadmap kill-criterion — the jump to backend work is meant
117	 * to be gated on it, and nothing measured it before `Build.repairAttempts`.
118	 */
119	export async function greenBuildRate(sinceDays = 30): Promise<{
120	  succeeded: number;
121	  firstTry: number;
122	  rate: number | null;
123	}> {
124	  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60 * 1000);
125	  const where = { status: "SUCCEEDED", createdAt: { gte: since } };
126	
127	  const [succeeded, firstTry] = await Promise.all([
128	    db.build.count({ where }),
129	    db.build.count({ where: { ...where, repairAttempts: 0 } }),
130	  ]);
131	
132	  return {
133	    succeeded,
134	    firstTry,
135	    rate: succeeded === 0 ? null : Math.round((firstTry / succeeded) * 1000) / 10,
136	  };
137	}
138	
139	/**
140	 * What people ask for AFTER a build, ranked. This is the learning-mode
141	 * scoreboard: the top bucket is, in aggregate, what the first generation gets
142	 * wrong most often, and therefore what the next prompt change should target.
143	 *
144	 * Buckets come from a heuristic (lib/feedback-intent.ts) and are only
145	 * meaningful in aggregate — see the caveats in that file.
146	 */
147	export async function followUpIntents(
148	  sinceDays = 30,
149	): Promise<{ intent: string; count: number; pct: number }[]> {
150	  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60 * 1000);
151	
152	  const rows = await db.event.findMany({
153	    where: { name: EVENTS.buildStarted, createdAt: { gte: since } },
154	    select: { props: true },
155	  });
156	
157	  const counts = new Map<string, number>();
158	  for (const row of rows) {
159	    const intent = (row.props as { intent?: unknown } | null)?.intent;
160	    // Absent on first builds, which have no follow-up to classify.
161	    if (typeof intent !== "string") continue;
162	    counts.set(intent, (counts.get(intent) ?? 0) + 1);
163	  }
164	
165	  const total = [...counts.values()].reduce((a, b) => a + b, 0);
166	  return [...counts.entries()]
167	    .map(([intent, count]) => ({
168	      intent,
169	      count,
170	      pct: total === 0 ? 0 : Math.round((count / total) * 1000) / 10,
171	    }))
172	    .sort((a, b) => b.count - a.count);
173	}
174	
175	/** Thumbs up/down on finished builds. */
176	export async function buildRatings(sinceDays = 30): Promise<{
177	  up: number;
178	  down: number;
179	  rated: number;
180	  satisfaction: number | null;
181	}> {
182	  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60 * 1000);
183	
184	  const rows = await db.event.findMany({
185	    where: { name: EVENTS.buildRated, createdAt: { gte: since } },
186	    select: { props: true },
187	  });
188	
189	  let up = 0;
190	  let down = 0;
191	  for (const row of rows) {
192	    const rating = (row.props as { rating?: unknown } | null)?.rating;
193	    if (rating === "up") up++;
194	    else if (rating === "down") down++;
195	  }
196	
197	  const rated = up + down;
198	  return { up, down, rated, satisfaction: rated === 0 ? null : Math.round((up / rated) * 1000) / 10 };
199	}
