// THROWAWAY test fixture for the retention job. Creates rows that are
// unmistakably mine (TAG below), then `node seed-throwaway.mjs clean` removes
// every one of them. Never run against anything but a local database.
import { loadEnv, quietNodeWarnings } from "../../../../../../../kodely-prod/scripts/eval/loader.mjs";

quietNodeWarnings();
try {
  loadEnv({ quiet: true });
} catch {
  /* KODELY_FOUNDATION_DIR is irrelevant here */
}

const { PrismaClient } = await import("@prisma/client");
const db = new PrismaClient();

const TAG = "retention-throwaway";
const day = 86_400_000;
const ago = (d) => new Date(Date.now() - d * day);
const mode = process.argv[2] ?? "seed";

async function clean() {
  const users = await db.user.findMany({ where: { email: { startsWith: TAG } }, select: { id: true } });
  for (const u of users) {
    await db.project.deleteMany({ where: { userId: u.id } });
    await db.event.deleteMany({ where: { userId: u.id } });
  }
  const ev = await db.event.deleteMany({ where: { name: { startsWith: TAG } } });
  const se = await db.stripeEvent.deleteMany({ where: { id: { startsWith: TAG } } });
  const us = await db.user.deleteMany({ where: { email: { startsWith: TAG } } });
  console.log(`cleaned: users=${us.count} events=${ev.count} stripeEvents=${se.count}`);
}

if (mode === "clean") {
  await clean();
  await db.$disconnect();
  process.exit(0);
}

await clean();

const user = await db.user.create({ data: { email: `${TAG}-${Date.now()}@example.invalid` } });
const project = await db.project.create({
  data: { userId: user.id, name: `${TAG} project`, slug: `${TAG}-${Date.now()}` },
});

// 25 successful builds, oldest 400d ago. Newest 20 keep their snapshot,
// the 5 oldest should be cleared (all are well past the 30d age floor).
const snapshot = {
  source: Object.fromEntries(Array.from({ length: 12 }, (_, i) => [`src/f${i}.tsx`, "x".repeat(4000)])),
  build: { "index.html": "y".repeat(4000) },
};
for (let i = 0; i < 25; i++) {
  await db.build.create({
    data: {
      projectId: project.id,
      status: "SUCCEEDED",
      model: "test",
      prompt: `throwaway build ${i}`,
      createdAt: ago(400 - i * 12),
      filesSnapshot: snapshot,
    },
  });
}

// 2 expired sessions + 1 live one.
for (const [n, expiresAt] of [
  ["a", ago(1)],
  ["b", ago(90)],
  ["c", new Date(Date.now() + 10 * day)],
]) {
  await db.session.create({ data: { userId: user.id, tokenHash: `${TAG}-${n}-${Date.now()}`, expiresAt } });
}

// 6 events past 400d, 4 inside it.
for (let i = 0; i < 10; i++) {
  await db.event.create({
    data: { userId: user.id, name: "user.signed_up", createdAt: ago(i < 6 ? 500 + i : 10) },
  });
}

// 2 Stripe records past 365d, 2 inside it.
for (let i = 0; i < 4; i++) {
  await db.stripeEvent.create({
    data: { id: `${TAG}-${i}-${Date.now()}`, type: "checkout.session.completed", createdAt: ago(i < 2 ? 400 : 5) },
  });
}

console.log(`seeded user=${user.id} project=${project.id}`);
console.log("expected: sessions=2 build-snapshots=5 events=6 stripe-events=2");
await db.$disconnect();

