const {readFileSync}=require('fs');
for (const l of readFileSync('.env','utf8').split(/\r?\n/)) { const i=l.indexOf('='); if(i>0&&!l.trim().startsWith('#')) { const k=l.slice(0,i).trim(); let v=l.slice(i+1).trim(); if(!(k in process.env)) process.env[k]=v.replace(/^['\"]|['\"]\$/g,''); } }
const {PrismaClient, Prisma}=require('@prisma/client');
const db=new PrismaClient();
const src=(cutoff)=>Prisma.sql\`
  FROM (
    SELECT b.id, b.\"filesSnapshot\" AS snapshot, b.\"createdAt\" AS created_at,
           row_number() OVER (PARTITION BY b.\"projectId\" ORDER BY b.\"createdAt\" DESC, b.id DESC) AS rn
    FROM \"Build\" b WHERE b.status = 'SUCCEEDED'
  ) ranked
  WHERE ranked.rn > \${20} AND ranked.created_at < \${cutoff} AND ranked.snapshot IS NOT NULL\`;
(async()=>{
  const cutoff=new Date(Date.now()-30*86400000);
  const ids = await db.\$queryRaw\`SELECT ranked.id \${src(cutoff)} ORDER BY ranked.created_at ASC LIMIT \${500}\`;
  console.log('batch id query OK, candidates =', ids.length);
  // Same fragment with a deliberately permissive cutoff+depth to prove the
  // window/LIMIT combination really returns rows and is not silently empty.
  const src2=(k,c)=>Prisma.sql\`FROM (SELECT b.id, b.\"filesSnapshot\" AS snapshot, b.\"createdAt\" AS created_at, row_number() OVER (PARTITION BY b.\"projectId\" ORDER BY b.\"createdAt\" DESC, b.id DESC) AS rn FROM \"Build\" b WHERE b.status='SUCCEEDED') ranked WHERE ranked.rn > \${k} AND ranked.created_at < \${c} AND ranked.snapshot IS NOT NULL\`;
  const probe = await db.\$queryRaw\`SELECT ranked.id \${src2(0,new Date())} ORDER BY ranked.created_at ASC LIMIT \${500}\`;
  console.log('sanity (depth 0, cutoff now) returns =', probe.length, 'ids');
  await db.\$disconnect();
})().catch(e=>{console.error('ERR',e.message.split('\n').slice(0,8).join(' '));process.exit(1)});
